            font.pixelSize: Theme.caption
            implicitWidth: 44
            Accessible.name: qsTr("Segmented view")
            onClicked: root.mlBridge.setBackgroundMode(1)
        }
        Binding {
            target: segViewButton
            property: "checked"
            value: root.mlBridge.backgroundMode === 1
        }
    }
